#include <iostream>
#include <memory>
#include <vector>
struct Shape { virtual ~Shape() = default; virtual int area() const = 0; };
struct Rectangle final : Shape { int width, height; Rectangle(int w, int h) : width(w), height(h) {} int area() const override { return width * height; } };
struct Square final : Shape { int side; explicit Square(int s) : side(s) {} int area() const override { return side * side; } };
int main() {
    std::vector<std::unique_ptr<Shape>> shapes;
    shapes.push_back(std::make_unique<Rectangle>(4, 5));
    shapes.push_back(std::make_unique<Square>(3));
    for (const auto& shape : shapes) std::cout << shape->area() << ' ';
    std::cout << '\n';
}
